// src/jsx/Chat/Private/PrivateChat.MessageComponents.jsx
import React, { useEffect, useRef } from "react";
import { formatTime, getMessageUrl, linkifyText } from "../../../js/Chat/PrivateChat.helpers.js";
import { emojify } from "../Emoji/EmojiParser.js";

export function linkifyAndEmojify(text) {
  if (!text) return "";

  // Detecta URLs
  const urlRegex = /(https?:\/\/[^\s]+)/gi;

  // Adiciona links clicáveis
  const html = text.replace(urlRegex, (url) => {
    return `<a 
      href="${url}" 
      target="_blank" 
      rel="noopener noreferrer"
      style="color:#0b66ff;text-decoration:underline;"
    >${url}</a>`;
  });

  // Aplica twemoji por último
  return emojify(html);
}
/**
 * MessageMenu: flutuante (3 pontos) — fecha ao clicar fora
 * props: msg, onEdit, onDeleteForMe, onDeleteForAll
 */
export function MessageMenu({ msg, onEdit, onDeleteForMe, onDeleteForAll, openMenuId, setOpenMenuId }) {
  const ref = useRef(null);

  useEffect(() => {
    function onDocClick(e) {
      if (ref.current && !ref.current.contains(e.target)) {
        setOpenMenuId(null);
      }
    }
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, [setOpenMenuId]);

  if (msg.from !== msg.currentUserId) return null;

  return (
    <div ref={ref} style={{ position: "absolute", top: -6, right: -6, zIndex: 60 }}>
      <button
        onClick={() => setOpenMenuId(openMenuId === msg.id ? null : msg.id)}
        style={{ background: "transparent", border: "none", cursor: "pointer", fontSize: 16 }}
        aria-label="menu"
      >
        ⋮
      </button>

      {openMenuId === msg.id && (
        <div className="message-menu" style={{
          position: "absolute",
          right: 0,
          top: 26,
          background: "#fff",
          border: "1px solid #eee",
          borderRadius: 8,
          boxShadow: "0 6px 14px rgba(0,0,0,0.10)",
          minWidth: 140
        }}>
          <div className="menu-item" onClick={() => { setOpenMenuId(null); onEdit(msg); }}>Editar</div>
          <div className="menu-item" onClick={() => { setOpenMenuId(null); onDeleteForMe(msg); }}>Excluir para mim</div>
          <div className="menu-item" onClick={() => { setOpenMenuId(null); onDeleteForAll(msg); }}>Excluir para todos</div>
        </div>
      )}
    </div>
  );
}


/**
 * MessageBubble: renderiza todos os tipos e aplica animação
 */
export function MessageBubble({ m, isMe, sender, currentUserId, openMenuId, setOpenMenuId, onEdit, onDeleteForMe, onDeleteForAll, linkClassName }) {
  const url = getMessageUrl(m.url);
  const overflowStyle = { maxWidth: 480, wordBreak: "break-word" };

  // linkify
  const content = m.text ? linkifyText(m.text, linkClassName) : null;

  return (
    <div className={`msg-wrap ${isMe ? "msg-me" : "msg-other"}`} style={{ display: "flex", justifyContent: isMe ? "flex-end" : "flex-start", marginBottom: 10, position: "relative" }}>
      {!isMe && <div style={{ marginRight: 8 }}><img src={sender?.avatarUrl || ""} alt="" style={{ width: 36, height: 36, borderRadius: 18, objectFit: "cover" }} /></div>}

      <div className={`msg ${isMe ? "me" : "other"} fade-in`} style={{ ...overflowStyle, position: "relative" }}>
        {/* Message menu (only for my messages) */}
        {isMe && <MessageMenu msg={{ ...m, currentUserId }} onEdit={onEdit} onDeleteForMe={onDeleteForMe} onDeleteForAll={onDeleteForAll} openMenuId={openMenuId} setOpenMenuId={setOpenMenuId} />}

        {/* deletedForAll */}
        {m.deletedForAll ? (
          <div style={{ fontStyle: "italic", color: "#666" }}>Mensagem excluída</div>
        ) : (
          <>
            {/* media + text below */}
            {m.type === "image" && url && (
              <>
                <img src={url} style={{ width: "100%", borderRadius: 8 }} alt="img" />
                {content && <div style={{ marginTop: 8 }}>{content}</div>}
              </>
            )}

            {m.type === "video" && url && (
              <>
                <video src={url} controls style={{ width: "100%", borderRadius: 8 }} />
                {content && <div style={{ marginTop: 8 }}>{content}</div>}
              </>
            )}

            {m.type === "audio" && url && <audio src={url} controls />}

            {m.type === "gif" && url && <img src={url} style={{ width: "100%", borderRadius: 8 }} alt="gif" />}

            {m.type === "file" && url && (
              <>
                <a href={url} target="_blank" rel="noopener noreferrer">{url.split("/").pop()}</a>
                {content && <div style={{ marginTop: 8 }}>{content}</div>}
              </>
            )}

            {/* text-only */}
            {(m.type === "text" || (!m.type && m.text)) && (
              <div style={{ whiteSpace: "pre-wrap" }}>{content}</div>
            )}
          </>
        )}

        {/* meta: time + edited + ticks */}
        <div className="hora" style={{ display: "flex", alignItems: "center", justifyContent: "flex-end", gap: 6, marginTop: 6 }}>
          <div style={{ fontSize: 11 }}>{formatTime(m.createdAt)}</div>
          {m.edited && <div style={{ fontSize: 11, opacity: 0.6 }}>(editada)</div>}
          {/* ticks handled by parent rendering usually via renderStatus */}
        </div>
      </div>
    </div>
  );
}
